insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('16ff4a51-d956-4ee9-bd1d-b820aaad519a', 'fr', 'Que veut dire savoir s’ajuster quand tu abordes en journée ?', '["Accorder ton énergie à la sienne", "T’ajuster selon ses signes de confort", "Garder un échange respectueux", "Toutes les réponses ci-dessus"]'::jsonb, 'S’ajuster, c’est être attentif en agissant : lire sa réaction et t’adapter en conséquence.')
