insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3e974466-6524-42dc-a429-63bb8e831188', 'fr', 'Pourquoi une accroche comme « Toi, tu fais du pilates, non ? » l’implique-t-elle tout de suite ?', '["Elle montre que tu as remarqué sa condition physique", "Elle crée une implication immédiate : elle doit corriger ou confirmer", "Elle montre que tu t’y connais en sport et en santé"]'::jsonb, 'Une supposition appelle une réponse. Elle est tout de suite impliquée pour corriger ou confirmer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1874cbce-d4aa-44b1-ab88-ff0c2745d69f', 'fr', 'Pourquoi les accroches par supposition accrochent-elles mieux que les questions passe-partout ?', '["Elles la rendent curieuse de ta perception", "On peut y répondre en pilote automatique", "Elles demandent une confirmation ou une correction"]'::jsonb, 'Une supposition lui donne le sentiment d’être vue et suscite une implication immédiate.')
