insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e84223a-e094-4ee6-8da9-79cd89d634c7', 'fr', '« J’ai besoin d’un avis féminin » marche parce que :', '["ça la rend curieuse de savoir sur quoi tu as besoin d’un avis", "elle sent que son point de vue est valorisé et important", "ça présente les femmes comme ayant un regard particulier dont tu as besoin", "toutes les réponses ci-dessus"]'::jsonb, 'Ça crée de la curiosité, la valorise et présente le point de vue féminin comme précieux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc959e07-994f-4a1d-b948-b437f3e6f2b2', 'fr', 'Tu commences par un dilemme. Elle te donne une réponse détaillée. Que pourrais-tu faire ensuite ?', '["Mettre fin à l’échange", "Approuver entièrement", "Changer de sujet", "Rebondir sur ce qu’elle a dit"]'::jsonb, 'Rebondir sur sa réponse récompense son effort et garde l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c800f82-c80b-490c-988f-e66f6100d311', 'fr', 'Quelles accroches valorisent son point de vue ?', '["« J’ai besoin d’un avis féminin »", "« Petite question pour toi »", "« Tu es très attirante »", "« Mon pote et moi, on débattait d’un truc »"]'::jsonb, 'Ces accroches lui donnent un rôle ; elle se sent incluse dès le départ.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43b03548-630d-4716-8d45-71c89fa4a819', 'fr', 'Qu’est-ce qu’une limite de temps quand on aborde ?', '["Un délai que tu lui donnes pour répondre à ton approche", "Une technique pour créer de l’urgence et de la rareté dans l’échange", "Une phrase d’ouverture qui indique que tu vas bientôt repartir"]'::jsonb, 'Annoncer que tu ne vas pas rester longtemps réduit la pression ; fais-le dès le début.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfb43838-50ce-4ae4-8c8a-722afd35d73a', 'fr', 'Quel est le but d’annoncer une limite de temps au début d’une approche ?', '["Contrôler l’échange en te présentant comme quelqu’un d’occupé", "Créer de la rareté pour qu’elle accorde plus de valeur à ton temps", "La mettre à l’aise en lui enlevant la pression d’un échange sans fin"]'::jsonb, 'Annoncer que tu ne vas pas rester longtemps réduit la pression ; fais-le dès le début.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66801814-05f0-417d-a387-606cb86e6cf9', 'fr', 'Tu abordes une femme dans un café. Que peux-tu dire en premier pour réduire la pression ?', '["Complimenter tout de suite son physique", "Dire que tu ne peux rester qu’une seconde", "Poser des questions personnelles et profondes", "Proposer d’aller ailleurs"]'::jsonb, 'Une limite de temps indique que tu vas bientôt partir, ce qui lui fait baisser la garde.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8993be7c-90eb-4430-96e6-83d657f55add', 'fr', 'Quels signes indiquent qu’il est temps de faire une fausse sortie ?', '["L’énergie est au plus haut, elle rit et elle est très impliquée", "La conversation vient de commencer, la complicité est encore en train de se créer", "Tu sens que l’énergie va plafonner ou retomber naturellement", "Vous parlez depuis exactement 10 minutes, quelle que soit l’énergie"]'::jsonb, 'Énergie au sommet ou plateau imminent : c’est le bon moment. Ce n’est pas une question de chrono arbitraire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c6866bb5-1e8c-4c24-9fa6-7ea784314163', 'fr', 'À quoi sert une fausse sortie ?', '["Créer un manque en partant avant que la conversation s’essouffle d’elle-même", "Montrer que tu as d’autres options : tu n’as pas besoin de tirer chaque seconde", "T’empêcher de glisser vers la recherche d’approbation", "Garantir qu’elle voudra forcément continuer plus tard"]'::jsonb, 'Créer un manque, montrer que tu as le choix, éviter la recherche d’approbation : voilà les bénéfices d’une fausse sortie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d51f94a-3406-49fb-98ed-99beb074d2bf', 'fr', '« C’était sympa, je vais faire un petit tour. Je reviens te voir tout à l’heure. » Tu t’éloignes. Qu’est-ce que ça a créé ?', '["Le risque qu’elle perde tout intérêt ou rencontre quelqu’un d’autre pendant ton absence", "Une impression positive et inachevée, avec la curiosité de te voir revenir", "Une confusion : est-ce que tu t’intéresses vraiment à elle ?", "La preuve que tu n’es pas vraiment décidé à la séduire"]'::jsonb, 'Partir au sommet = un souvenir positif + un manque qui rend curieuse. Elle en veut plus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30461b26-dac7-40f7-ae3f-bc7f90b1ebcb', 'fr', 'Quelle est la différence entre ne pas aborder et se faire rejeter ?', '["Le rejet fait plus mal sur le moment", "Ne pas aborder protège ton ego et ta confiance", "Le rejet te donne de l’expérience ; ne pas aborder ne te donne rien"]'::jsonb, 'Dans les deux cas, pas de lien, mais le rejet te donne de l’expérience pour les approches suivantes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('46975d8e-4143-4ea5-9c92-bde52c3bebad', 'fr', 'Quel est le pire résultat possible quand il s’agit d’aborder ?', '["Un refus poli", "Une courte conversation ratée", "Le regret de ne pas avoir agi", "Un silence gênant"]'::jsonb, 'Le regret d’une occasion manquée dure plus longtemps qu’un bref refus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('05af8c26-1d5f-4746-bd8d-93ffa9ceb943', 'fr', 'Pourquoi un refus vaut-il mieux que ne pas aborder ?', '["Il garantit un regret durable", "Il apporte de l’expérience et des informations", "Il crée une possibilité de lien", "Il supprime toute incertitude"]'::jsonb, 'L’action ouvre des portes ; l’inaction les ferme à coup sûr.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3400a772-93ac-48a3-a167-060ae3d525d8', 'fr', 'Qu’est-ce qui est à l’origine de presque tous les liens dans la vie ?', '["Des centres d’intérêt communs", "Le bon timing", "La confiance en soi", "Quelqu’un qui parle en premier"]'::jsonb, 'Tous les liens commencent parce que quelqu’un fait le premier pas et parle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bf5ff661-2958-4e0d-ab57-b3ef0436b379', 'fr', 'Tu es à la soirée d’un ami et tu ne connais presque personne. Que pourrais-tu faire en premier ?', '["Rester silencieux dans un coin jusqu’à ce que quelqu’un vienne vers toi", "Demander à quelqu’un comment il connaît l’hôte", "Attendre la phrase d’accroche parfaite", "Partir tôt pour éviter la gêne"]'::jsonb, 'Parler en premier crée des occasions ; le silence n’en crée aucune.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('833fb7a5-48fa-44ca-bb33-3134723fc718', 'fr', 'À quoi peut mener le fait d’ouvrir la bouche ?', '["De nouvelles amitiés", "De nouvelles expériences", "Une réussite garantie", "Des occasions inattendues"]'::jsonb, 'Aller vers les autres ouvre l’accès à toutes sortes de résultats.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('588b3d53-613d-4e21-bdeb-77f6157427c7', 'fr', 'Pourquoi aborder avec curiosité plutôt qu’avec un objectif ?', '["La curiosité est plus discrète, l’objectif plus assuré", "La curiosité évite l’attirance, l’objectif la crée", "La curiosité découvre qui elle est, l’objectif cherche un résultat"]'::jsonb, 'La curiosité explore la personne. Un objectif cherche à en tirer un résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4003461a-b8aa-4eaa-b66f-3d5847986f38', 'fr', 'Tu remarques des autocollants d’Islande sur son ordinateur. Quelle accroche montre une vraie curiosité ?', '["« Salut, je t’ai trouvée mignonne et j’avais envie de te rencontrer. »", "« Je peux t’offrir un café ? »", "« Tu as l’air de beaucoup voyager. »", "« C’est un autocollant d’Islande ? J’y étais l’an dernier. »"]'::jsonb, 'Être curieux de ce qu’elle a vécu invite un vrai lien, sans arrière-pensée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d398047f-31f2-46cb-991f-abb7e05f231d', 'fr', 'Pourquoi aborder avec curiosité crée-t-il des liens plus forts qu’avec un objectif ?', '["Ça fait d’elle un objectif à atteindre", "Elle se sent intéressante et vue", "Ça enlève la pression d’obtenir un résultat", "Ça permet une conversation plus facile et plus authentique"]'::jsonb, 'La curiosité se concentre sur elle en tant que personne, ce qui favorise un lien naturel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7265d45c-cbbc-4d5e-8220-2d1c5fe793f2', 'fr', 'Pourquoi aborder paraît-il plus difficile quand on le fait rarement ?', '["L’enjeu paraît plus élevé", "Il y a moins de chances de réussir", "Le timing est moins bon", "La peur augmente"]'::jsonb, 'Quand les approches sont rares, chacune pèse plus lourd et paraît plus intense.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31e5395b-0177-4703-8182-44c9921a16fc', 'fr', 'Quelle erreur pousse les gens à aborder moins qu’ils ne le pourraient ?', '["Être dans de mauvais endroits", "Attendre les conditions idéales", "Être sur leur téléphone", "Le manque d’intérêt"]'::jsonb, 'Attendre des conditions parfaites réduit le nombre total d’occasions. Tu peux aborder n’importe quand.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b04aa8-e3ca-474a-af0c-4aac0238c9b5', 'fr', 'Quelles habitudes te maintiennent régulièrement en contact avec les autres ?', '["Parler à des inconnus tout au long de ta journée", "Voir chaque endroit comme un lieu où t’entraîner à créer du lien", "N’aborder que quand tu te sens totalement sûr de toi"]'::jsonb, 'Aller régulièrement vers les autres réduit la pression et rend les échanges plus faciles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cd29e03-754c-4a91-8b5a-132fe680704d', 'fr', 'À quoi sert la règle des trois secondes ?', '["Créer un sentiment d’urgence", "Éviter le rejet", "Peaufiner tes accroches", "Agir avant que la résistance ne s’installe"]'::jsonb, 'Agir vite empêche le doute de s’installer. Bouge dans les trois secondes après l’avoir remarquée.')
